// instrumentation.node.js — flush OpenTelemetry before the process exits, generated by otel-as-code
// Only effective with NEXT_MANUAL_SIG_HANDLE=true in the deployment environment: without it Next's
// own SIGTERM cleanup exits first and the last batch of spans is lost.
import { trace } from "@opentelemetry/api";

let stopping = false;
async function stop(code) {
  if (stopping) return;
  stopping = true;
  try {
    const provider = trace.getTracerProvider();
    const target = typeof provider.getDelegate === "function" ? provider.getDelegate() : provider;
    // Bounded: a slow backend must not keep the container from stopping.
    await Promise.race([target.shutdown?.(), new Promise((resolve) => setTimeout(resolve, 5000))]);
  } catch (err) {
    console.error("Error flushing OpenTelemetry on shutdown", err);
  } finally {
    process.exit(code);
  }
}
process.on("SIGTERM", () => void stop(0));
process.on("SIGINT", () => void stop(0));
